//! Regression coverage for task #546: a post-build failure for ONE language used to skip the
//! terminal `finalize_hashes`/`finalize_hashes_sweeping` stamp for the WHOLE crate, leaving
//! every language's freshly-written output that run -- not just the failing language's --
//! carrying its `// This file is auto-generated by alef` header with no `alef:hash:` line.
//!
//! `Commands::Generate`'s `complete_generated_artifacts` call used to propagate a post-build
//! error with a bare `return Err(error)`, straight out of `handle_generate`, before the single
//! terminal stamp call for that crate ever ran. Because a stamp is only ever written when
//! content actually changes (`write_files_report` compares hash-stripped bodies and no-ops when
//! they already match), a file left unstamped this way never gets a second chance on a later
//! run either: as long as its own content is unchanged, every subsequent run treats it as a
//! cache hit and never re-enters the path that would stamp it, and as long as the SAME
//! post-build step keeps failing (a persistently broken toolchain, not a one-off interruption),
//! every subsequent run hits the exact same early return. The measured incident (a consumer
//! repo mostly driven by `alef generate`, not `alef all`) showed this cross five different
//! backends in one run -- python's `api.py`, node's `index.d.ts`, go's `visitor.go`, php's
//! public API class and PHP extension stub, and ruby's `native.rb` -- which is the signature of
//! a single shared write-path gap, not five independent per-backend bugs: every one of those
//! files is written by a phase that ran and completed successfully in that same run, and the
//! only thing they have in common is that the crate's post-build step for some OTHER language
//! failed afterward.
//!
//! `alef all` (`all_commands.rs`) was already fixed for the identical hazard (`stage_failures`,
//! task #186); `Commands::Generate` was not. Both commands now defer the error into the same
//! `StageFailures` type instead of hard-returning.

use crate::bin_cli::args::Commands;
use crate::bin_cli::dispatch::DispatchContext;
use crate::core::backend::GeneratedFile;
use crate::core::config::Language;
use std::path::{Path, PathBuf};

const FIXTURE_SOURCE: &str = "pub fn greet(name: String) -> String {\n    format!(\"hello, {name}\")\n}\n";
const FIXTURE_CARGO_TOML: &str = "[package]\nname = \"stamp-fixture\"\nversion = \"0.1.0\"\nedition = \"2024\"\n";

/// A crate configured for two languages: python (a healthy phase this test needs written and
/// stamped) and swift (a phase whose post-build genuinely fails against this fixture -- no real
/// swift-bridge build project exists here, and nothing seeds one). `generate_public_api`
/// (`pyo3::gen_bindings::public_files`) derives its output root from the crate `name` with `-`
/// replaced by `_` when no `[crates.python.stubs] output` override is configured (it is not,
/// here), so `packages/python/stamp_fixture/` is the resulting root the test asserts against
/// below.
const MIXED_FIXTURE_ALEF_TOML: &str = r#"
[workspace]
languages = ["python", "swift"]

[[crates]]
name = "stamp-fixture"
sources = ["src/lib.rs"]
version_from = "Cargo.toml"
"#;

/// The property test's own fixture: python (public API) and node (self-marking `index.d.ts`),
/// with no swift/post-build failure involved at all -- a healthy-run control for
/// [`every_marked_generated_file_is_stamped_after_generate`].
const PYTHON_NODE_FIXTURE_ALEF_TOML: &str = r#"
[workspace]
languages = ["python", "node"]

[[crates]]
name = "stamp-fixture"
sources = ["src/lib.rs"]
version_from = "Cargo.toml"
"#;

fn write_mixed_fixture_workspace(root: &Path) {
    std::fs::create_dir_all(root.join("src")).expect("create fixture src directory");
    std::fs::write(root.join("src/lib.rs"), FIXTURE_SOURCE).expect("write fixture source");
    std::fs::write(root.join("Cargo.toml"), FIXTURE_CARGO_TOML).expect("write fixture Cargo.toml");
    std::fs::write(root.join("alef.toml"), MIXED_FIXTURE_ALEF_TOML).expect("write fixture alef.toml");
    std::fs::write(root.join("Cargo.lock"), "").expect("write fixture Cargo.lock");
    // Same swift package-root workaround `post_build_format_order_tests::write_fixture_workspace`
    // uses, for the same reason (see that function's doc): without it, swift's in-process
    // bindings phase misplaces `Sources/` at the repo root on a project with no
    // `packages/swift/Sources` yet. This test does not care whether swift's bindings phase
    // succeeds -- only that its POST-BUILD step fails -- but a misplaced `Sources/` tree can
    // itself throw, which would fail the run for the wrong reason before it ever reaches
    // post-build. ~keep
    std::fs::create_dir_all(root.join("packages/swift/Sources")).expect("create packages/swift/Sources");
}

/// The python public-API output root `pyo3::gen_bindings::public_files::generate_public_api`
/// resolves for this fixture's crate name (`packages/python/{name with - to _}`).
fn python_output_dir(root: &Path) -> PathBuf {
    root.join("packages/python/stamp_fixture")
}

/// Run `alef generate` (no `--lang` filter, so both configured languages run) against `root`,
/// with `ALEF_SKIP_COMMANDS` forced empty so swift's post-build genuinely attempts (and fails)
/// a real `cargo build`, rather than taking the deterministic `ALEF_SKIP_COMMANDS` skip path
/// `post_build_format_order_tests::run_generate` relies on for its own, unrelated fixture. Held
/// for the whole call, like `post_build::tests::required_post_build_failure_is_propagated_with_language_context`,
/// because `ALEF_SKIP_COMMANDS` is process-global and a concurrent test setting it to skip cargo
/// would turn this failure into a false pass. ~keep
fn run_generate_expecting_post_build_failure(root: &Path) -> anyhow::Error {
    let _skip_guard = crate::test_support::SkipCommandsGuard::set("");
    let _cwd = crate::test_support::CwdGuard::enter(root);
    let context = DispatchContext {
        config_path: root.join("alef.toml"),
        crate_filter: Vec::new(),
    };
    super::handle(
        Commands::Generate {
            lang: None,
            clean: false,
            skip_frb: false,
            strict: false,
            skip_compile: false,
        },
        &context,
    )
    .err()
    .expect("swift's post-build must fail for real against a fixture with no swift-bridge build project")
}

/// The decisive regression test: swift's post-build failure must not stop python's public API
/// output from being written AND stamped in the same run.
#[test]
fn generate_stamps_every_language_even_when_one_languages_post_build_fails() {
    let Some(_poly_on_path) = crate::test_support::tool_available_with_stable_path("poly") else {
        return;
    };
    let dir = tempfile::tempdir().expect("tempdir");
    let root = dir.path().canonicalize().unwrap_or_else(|_| dir.path().to_path_buf());
    write_mixed_fixture_workspace(&root);

    let error = run_generate_expecting_post_build_failure(&root);
    let message = format!("{error:#}");
    assert!(
        message.to_lowercase().contains("swift"),
        "the command must still fail and name the failing language, or this test is not \
         exercising the post-build failure path at all: {message}"
    );

    // The regression assertion: python's public API phase ran to completion (a phase entirely
    // independent of swift's post-build step) and its output must be BOTH present and stamped,
    // despite the overall command returning an error because of swift.
    let api_py = python_output_dir(&root).join("api.py");
    let content = std::fs::read_to_string(&api_py).unwrap_or_else(|error| {
        panic!("python's public API file must be written regardless of swift's post-build failure: {error}")
    });
    assert!(
        crate::core::hash::content_has_alef_marker(&content),
        "sanity: api.py must carry alef's provenance marker, or the assertion below is checking \
         a file alef does not claim to own: {content}"
    );
    assert!(
        content.contains("alef:hash:"),
        "python's api.py must still be stamped even though swift's post-build failed in the same \
         run -- before the fix, the post-build failure's bare `return Err` skipped the terminal \
         `finalize_hashes` call for the entire crate, leaving every language's freshly-written \
         output (not just swift's) with a header and no hash line. Got:\n{content}"
    );

    // A second, independent public-API file from the same phase, to rule out "one file happened
    // to already be stamped from an earlier write" as an explanation.
    let options_py = python_output_dir(&root).join("options.py");
    let options_content = std::fs::read_to_string(&options_py).expect("python's options.py must also be written");
    assert!(
        options_content.contains("alef:hash:"),
        "options.py must also be stamped in the same run: {options_content}"
    );
}

/// Every relative output path the generator itself claims should carry an `alef:hash:` stamp
/// for `root`, across bindings, service API, public API and type stubs -- the same
/// `GeneratedFile::carries_alef_marker()` predicate `stampable_output_paths` (and therefore
/// `finalize_hashes`/`finalize_hashes_sweeping`) uses to decide what must be re-stamped.
///
/// Read-only (`write_cache: false` for the bindings phase): this must not disturb `.alef/`'s
/// per-language cache, which the real `alef generate` run this test drives separately still
/// needs to see as cold.
fn expected_stamped_relative_paths(root: &Path) -> std::collections::HashSet<PathBuf> {
    let _cwd = crate::test_support::CwdGuard::enter(root);
    let config_path = root.join("alef.toml");
    let (_, resolved) = crate::bin_cli::helpers::load_config(&config_path).expect("load fixture alef.toml");
    let config = resolved.first().expect("fixture declares exactly one crate");
    let languages = crate::bin_cli::helpers::resolve_languages(config, None).expect("resolve fixture languages");
    let api = crate::cli::pipeline::extract(config, &config_path, true).expect("extract fixture API surface");

    let mut paths: std::collections::HashSet<PathBuf> = std::collections::HashSet::new();
    let mut collect = |phase: Vec<(Language, Vec<GeneratedFile>)>| {
        for (_, generated) in phase {
            for file in generated {
                if file.carries_alef_marker() {
                    paths.insert(file.path);
                }
            }
        }
    };

    collect(
        crate::cli::pipeline::generate(&api, config, &languages, true, &config_path, false)
            .expect("generate fixture bindings"),
    );
    collect(
        crate::cli::pipeline::generate_service_api(&api, config, &languages).expect("generate fixture service API"),
    );
    collect(
        crate::cli::pipeline::generate_public_api(&api, config, &languages, &config_path)
            .expect("generate fixture public API"),
    );
    collect(crate::cli::pipeline::generate_stubs(&api, config, &languages).expect("generate fixture type stubs"));

    paths
}

/// The property test this task's fix exists for: EVERY file kind the generator marks
/// alef-owned, for a healthy (no post-build failure) multi-language run, ships stamped. A test
/// enumerating only the eight paths one incident happened to surface (python's `api.py`, node's
/// `index.d.ts`, ...) would pass forever while the next backend or file kind that reintroduces
/// the same gap goes unnoticed -- this asks the generator itself which paths it claims, so a
/// newly added file kind is covered automatically. Node is included alongside python
/// specifically because its `index.d.ts` self-marks its header inline
/// (`generated_header: false`, with `hash::header(..)` baked into the emitted content by
/// `napi::gen_bindings::errors::gen_dts`) -- the same "backend bakes the header itself" shape
/// go's `visitor.go`, php's public API class and ruby's `native.rb` all share, distinct from
/// python's public API files, which use the plain `generated_header: true` prepend path. ~keep
#[test]
fn every_marked_generated_file_is_stamped_after_generate() {
    let Some(_poly_on_path) = crate::test_support::tool_available_with_stable_path("poly") else {
        return;
    };
    let dir = tempfile::tempdir().expect("tempdir");
    let root = dir.path().canonicalize().unwrap_or_else(|_| dir.path().to_path_buf());
    std::fs::create_dir_all(root.join("src")).expect("create fixture src directory");
    std::fs::write(root.join("src/lib.rs"), FIXTURE_SOURCE).expect("write fixture source");
    std::fs::write(root.join("Cargo.toml"), FIXTURE_CARGO_TOML).expect("write fixture Cargo.toml");
    std::fs::write(root.join("alef.toml"), PYTHON_NODE_FIXTURE_ALEF_TOML).expect("write fixture alef.toml");
    std::fs::write(root.join("Cargo.lock"), "").expect("write fixture Cargo.lock");

    let expected = expected_stamped_relative_paths(&root);
    assert!(
        !expected.is_empty(),
        "control failed: the generator claimed zero alef-marked files for this fixture, so the \
         assertion below would vacuously pass over an empty set"
    );

    let _skip_guard = crate::test_support::SkipCommandsGuard::set("cargo");
    let _cwd = crate::test_support::CwdGuard::enter(&root);
    let context = DispatchContext {
        config_path: root.join("alef.toml"),
        crate_filter: Vec::new(),
    };
    super::handle(
        Commands::Generate {
            lang: None,
            clean: false,
            skip_frb: true,
            strict: false,
            skip_compile: false,
        },
        &context,
    )
    .expect("alef generate must succeed against this fixture");
    drop(_cwd);

    let mut unstamped: Vec<String> = Vec::new();
    for relative in &expected {
        let full = root.join(relative);
        let content = match std::fs::read_to_string(&full) {
            Ok(content) => content,
            Err(error) => {
                unstamped.push(format!("{} (unreadable: {error})", relative.display()));
                continue;
            }
        };
        if !content.contains("alef:hash:") {
            unstamped.push(relative.display().to_string());
        }
    }
    assert!(
        unstamped.is_empty(),
        "every generator-claimed alef-marked file must carry an `alef:hash:` stamp after `alef \
         generate`, but these do not:\n  {}",
        unstamped.join("\n  ")
    );
}
